import{_ as t,o as e,c as s,aA as i}from"./chunks/framework.BVAahuVE.js";const g=JSON.parse('{"title":"Translation Guide","description":"","frontmatter":{},"headers":[],"relativePath":"translation.md","filePath":"translation.md","lastUpdated":null}'),n={name:"translation.md"};function l(o,a,d,r,p,h){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="Translation-Guide" tabindex="-1">Translation Guide <a class="header-anchor" href="#Translation-Guide" aria-label="Permalink to &quot;Translation Guide {#Translation-Guide}&quot;">​</a></h1><p>AlgebraOfVega translates AoG <code>Layer</code> / <code>Layers</code> objects to Vega-Lite JSON by reading the raw struct fields (<code>.data</code>, <code>.positional</code>, <code>.named</code>, <code>.transformation</code>).</p><h2 id="Translation-pipeline" tabindex="-1">Translation pipeline <a class="header-anchor" href="#Translation-pipeline" aria-label="Permalink to &quot;Translation pipeline {#Translation-pipeline}&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AoG Layer → check transformation chain for known analyses:</span></span>
<span class="line"><span>  → TidybayesAnalysis  → analysis_to_vl()     (multi-layer VL spec)</span></span>
<span class="line"><span>  → DensityAnalysis     → density_to_vl()      (VL density transform)</span></span>
<span class="line"><span>  → FrequencyAnalysis   → frequency_to_vl()    (VL aggregate count)</span></span>
<span class="line"><span>  → ExpectationAnalysis → expectation_to_vl()  (VL aggregate mean)</span></span>
<span class="line"><span>  → LinearAnalysis      → linear_to_vl()       (VL regression transform)</span></span>
<span class="line"><span>  → SmoothAnalysis      → smooth_to_vl()       (VL loess transform)</span></span>
<span class="line"><span>  → HistogramAnalysis   → histogram_to_vl()    (VL bin + bar)</span></span>
<span class="line"><span>  → (standard path):</span></span>
<span class="line"><span>      extract_data()    → Vega inline &quot;values&quot;</span></span>
<span class="line"><span>      extract_visual()  → Vega mark type + properties</span></span>
<span class="line"><span>      positional args   → x/y encoding channels</span></span>
<span class="line"><span>      named args        → color/size/shape/etc channels</span></span>
<span class="line"><span>      infer_types!()    → quantitative/nominal/ordinal</span></span>
<span class="line"><span>      auto-tooltip      → from all mapped fields</span></span>
<span class="line"><span>  → config properties merged on top (encoding deep-merged per channel)</span></span></code></pre></div><h2 id="Named-argument-mapping" tabindex="-1">Named argument mapping <a class="header-anchor" href="#Named-argument-mapping" aria-label="Permalink to &quot;Named argument mapping {#Named-argument-mapping}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">AoG kwarg</th><th style="text-align:right;">Vega-Lite channel</th></tr></thead><tbody><tr><td style="text-align:right;"><code>color</code></td><td style="text-align:right;">color</td></tr><tr><td style="text-align:right;"><code>marker</code></td><td style="text-align:right;">shape</td></tr><tr><td style="text-align:right;"><code>markersize</code></td><td style="text-align:right;">size</td></tr><tr><td style="text-align:right;"><code>dodge_x</code></td><td style="text-align:right;">xOffset</td></tr><tr><td style="text-align:right;"><code>dodge_y</code></td><td style="text-align:right;">yOffset</td></tr><tr><td style="text-align:right;"><code>col</code></td><td style="text-align:right;">column (facet)</td></tr><tr><td style="text-align:right;"><code>row</code></td><td style="text-align:right;">row (facet)</td></tr><tr><td style="text-align:right;"><code>group</code></td><td style="text-align:right;">detail</td></tr></tbody></table><h2 id="Positional-channel-mapping" tabindex="-1">Positional channel mapping <a class="header-anchor" href="#Positional-channel-mapping" aria-label="Permalink to &quot;Positional channel mapping {#Positional-channel-mapping}&quot;">​</a></h2><p>Most mark types map the first two positional arguments to <code>x</code> and <code>y</code>. Exceptions:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Mark type</th><th style="text-align:right;">Positional channels</th></tr></thead><tbody><tr><td style="text-align:right;"><code>HLines</code></td><td style="text-align:right;"><code>[y]</code> (first positional → y only)</td></tr><tr><td style="text-align:right;"><code>VLines</code></td><td style="text-align:right;"><code>[x]</code> (first positional → x only)</td></tr><tr><td style="text-align:right;"><code>Rangebars</code> / <code>Errorbars</code></td><td style="text-align:right;"><code>[x, y, y2]</code></td></tr><tr><td style="text-align:right;">All others</td><td style="text-align:right;"><code>[x, y]</code></td></tr></tbody></table><h2 id="Config-deep-merge" tabindex="-1">Config deep-merge <a class="header-anchor" href="#Config-deep-merge" aria-label="Permalink to &quot;Config deep-merge {#Config-deep-merge}&quot;">​</a></h2><p><code>config(encoding=...)</code> is deep-merged per channel. This means you can add properties to auto-generated encodings without losing the <code>field</code> and <code>type</code>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Adds aggregate to the auto-generated y encoding</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(encoding</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Dict</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;y&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Dict</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;aggregate&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;mean&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)))</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Adds log scale to x</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(encoding</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Dict</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;x&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Dict</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;scale&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Dict</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;type&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;log&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))))</span></span></code></pre></div><h2 id="Confidence-bands" tabindex="-1">Confidence bands <a class="header-anchor" href="#Confidence-bands" aria-label="Permalink to &quot;Confidence bands {#Confidence-bands}&quot;">​</a></h2><p>Vega-Lite&#39;s native <code>errorband</code> requires multiple observations per x value, which typical scatter data doesn&#39;t have. When <code>interval=:confidence</code> is set on <code>linear()</code> or <code>smooth()</code>, the CI is computed in Julia:</p><ul><li><p><strong><code>linear</code></strong>: Analytic regression CI using standard error of the mean response</p></li><li><p><strong><code>smooth</code></strong>: Moving-window weighted mean ± SE with tricube weights</p></li></ul><p>The CI data is embedded as a separate area+y2 layer with its own inline data.</p><h2 id="Faceted-specs" tabindex="-1">Faceted specs <a class="header-anchor" href="#Faceted-specs" aria-label="Permalink to &quot;Faceted specs {#Faceted-specs}&quot;">​</a></h2><p>For faceted specs (using <code>col=</code> or <code>row=</code> in mapping), config <code>width</code>/<code>height</code> are routed to the inner <code>spec</code> dict (per-cell size), not the top level (total size).</p>`,18)])])}const k=t(n,[["render",l]]);export{g as __pageData,k as default};
